// ─── File: StackHeapDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.sh;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StackHeapDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 'rajesh'/'priya' = reference variables on the STACK frame of main().
        // The Account OBJECTS they point to live on the HEAP.
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        InterestCalculator calc = new InterestCalculator();

        BigDecimal r1 = calc.yearlyInterest(rajesh, 4); // 4% rate
        BigDecimal r2 = calc.yearlyInterest(priya, 3);  // 3% rate

        log.info(() -> "Rajesh (heap object) yearly interest: Rs." + r1);
        log.info(() -> "Priya  (heap object) yearly interest: Rs." + r2);
        log.info(() -> "Note: 'ratePercent' and loop index were STACK locals; "
                + "Account objects were on the HEAP.");
    }
}

// ─── Would be in Account.java (object lives on HEAP) ───
class Account {
    private final String accountId;    // field → inside the heap object
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in InterestCalculator.java ───
class InterestCalculator {
    // 'account' reference + 'ratePercent' primitive live on THIS thread's STACK.
    BigDecimal yearlyInterest(Account account, int ratePercent) {
        // ratePercent is a STACK-resident primitive (fast, auto-freed).
        BigDecimal rate = BigDecimal.valueOf(ratePercent)
                .divide(BigDecimal.valueOf(100)); // local reference → stack handle
        // balance is read from the HEAP object via the reference.
        BigDecimal interest = account.getBalance().multiply(rate);
        // When this method returns, its stack frame (rate, ratePercent) is popped.
        return interest.setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
